body.--OT-highlight-fg-auto:
color-mix(
											in oklab,
											var(--OT-ink-active) 72%,
											color-mix(in oklab, var(--OT-highlight-bg) 35%, black) 28%
											)

body.styled-scrollbars.--OT-highlight-fg-auto:
color-mix(
											in oklab,
											var(--OT-ink-active) 72%,
											color-mix(in oklab, var(--OT-highlight-bg) 35%, black) 28%
											)
